#include "zopcodes.h"

void	dump_file(const bool bigend, const char *fn) {
	const	int	NZIP = 4096;
	char	ln[NZIP], lb[NZIP];
	ZIPI	ibuf[NZIP];
	FILE	*fp;
	int	nr;
	int	addr=0x08000;

	fp = fopen(fn, "r");
	if (!fp)
		return;
	printf("%s:\n", fn);
	while((nr=fread(ibuf, sizeof(ZIPI), NZIP, fp))>0) {
		for(int i=0; i<nr; i++) {
			if (bigend) {
				ZIPI bei, lei = ibuf[i];
				bei  = lei&0x0ff; bei<<=8; lei>>= 8;
				bei |= lei&0x0ff; bei<<=8; lei>>= 8;
